/**
 * A published music pack (generated by `npm run music:pack`, never edited): the runtime music
 * configuration plus exactly the patterns a human approved (or, in the explicit demo mode, the
 * temporary demos), each with its content hash and license. The game player only reads packs.
 */
import { buildCatalog } from './core/catalog';
import type {
  ArrangementDocument,
  EraDocument,
  MotifDocument,
  PatternDocument,
  PresetDocument,
} from './data/patterns.generated';
import { createLibrary, type MusicLibrary } from './library';

export interface PackEntry {
  readonly id: string;
  readonly revision: number;
  readonly eraId: string;
  readonly contentHash: string;
  readonly license: string;
  readonly attribution?: string;
  readonly composer?: string;
  readonly demo: boolean;
}

export interface MusicPack {
  readonly schemaVersion: 1;
  readonly mode: 'approved' | 'demo';
  readonly eras: readonly EraDocument[];
  readonly presets: readonly PresetDocument[];
  readonly arrangements: readonly ArrangementDocument[];
  readonly motifs: readonly MotifDocument[];
  readonly patterns: readonly PatternDocument[];
  readonly manifest: readonly PackEntry[];
  /** Build-time notes (e.g. empty banks) kept for dev diagnostics. */
  readonly diagnostics: readonly string[];
}

export function libraryFromPack(pack: MusicPack): MusicLibrary {
  const { catalog } = buildCatalog({
    eras: pack.eras,
    presets: pack.presets,
    arrangements: pack.arrangements,
    motifs: pack.motifs,
    patterns: pack.patterns,
  });
  const keys = new Set(pack.manifest.map((m) => `${m.id}@${m.revision}`));
  return pack.mode === 'demo'
    ? createLibrary(catalog, { candidates: 'demo' })
    : createLibrary(catalog, { candidates: 'approved', approved: keys });
}
